<script setup lang="ts">
import{onUnmounted,ref,watch}from'vue';
interface Recognition{lang:string;continuous:boolean;interimResults:boolean;onresult:((event:{resultIndex:number;results:ArrayLike<{isFinal:boolean;[index:number]:{transcript:string}}>})=>void)|null;onerror:((event:{error:string})=>void)|null;onend:(()=>void)|null;start():void;stop():void;abort():void}
type SpeechWindow=Window&{SpeechRecognition?:new()=>Recognition;webkitSpeechRecognition?:new()=>Recognition};
const props=defineProps<{disabled?:boolean}>();const emit=defineEmits<{text:[value:string]}>(),listening=ref(false),error=ref(''),transcribing=ref(false),viaGemini=ref(false);let recognition:Recognition|undefined;
const constructor=(window as SpeechWindow).SpeechRecognition??(window as SpeechWindow).webkitSpeechRecognition;
const recordingSupported=typeof MediaRecorder!=='undefined'&&!!navigator.mediaDevices?.getUserMedia;
let recorder:MediaRecorder|undefined,media:MediaStream|undefined,deadline:ReturnType<typeof setTimeout>|undefined,audioController:AbortController|undefined,disposed=false,captureRevision=0;
function stopCapture(discard=false){if(discard){captureRevision++;if(recorder){recorder.onstop=null;recorder.ondataavailable=null;}audioController?.abort();transcribing.value=false;viaGemini.value=false;}clearTimeout(deadline);if(recorder&&recorder.state!=='inactive'){try{recorder.stop();}catch{}}media?.getTracks().forEach(track=>track.stop());if(discard)listening.value=false;}
async function record(){
 const revision=++captureRevision;listening.value=true;viaGemini.value=true;error.value='';
 try{const type=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'].find(value=>MediaRecorder.isTypeSupported(value));if(!type)throw new Error('Este navegador no ofrece un formato de audio compatible. Usa Chrome o Edge.');const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(disposed||revision!==captureRevision||props.disabled){stream.getTracks().forEach(track=>track.stop());return;}media=stream;recorder=new MediaRecorder(stream,{mimeType:type,audioBitsPerSecond:32000});const chunks:Blob[]=[];let bytes=0;
 recorder.ondataavailable=event=>{if(event.data.size){bytes+=event.data.size;if(bytes>2*1024*1024){error.value='El audio supera 2 MB. Graba un mensaje más breve.';stopCapture(true);}else chunks.push(event.data);}};
 recorder.onerror=()=>{error.value='No se pudo grabar el audio.';stopCapture(true);};
 const active=recorder;
 recorder.onstop=async()=>{clearTimeout(deadline);stream.getTracks().forEach(track=>track.stop());listening.value=false;if(disposed||revision!==captureRevision||props.disabled)return;transcribing.value=true;const currentController=new AbortController();audioController=currentController;
  try{const blob=new Blob(chunks,{type}),data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]??'');reader.onerror=()=>reject(new Error('No se pudo leer el audio.'));reader.readAsDataURL(blob);});if(disposed||revision!==captureRevision)return;
   const response=await fetch('/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:'audio',audio:{mimeType:type.startsWith('audio/mp4')?'audio/m4a':type.split(';')[0],data}}),signal:currentController.signal});const result=await response.json().catch(()=>null);if(!response.ok)throw new Error(result?.error?.message??'No se pudo transcribir el audio.');if(typeof result?.content!=='string'||!result.content.trim()||result.content.includes('[Sin habla reconocible]'))throw new Error('No se reconoció habla. Intenta dictar otra vez.');if(!disposed&&revision===captureRevision)emit('text',result.content.trim());
  }catch(cause){if(!disposed&&revision===captureRevision)error.value=(cause as Error).message;}finally{chunks.length=0;active.onstop=null;active.ondataavailable=null;if(recorder===active)recorder=undefined;if(media===stream)media=undefined;if(revision===captureRevision){transcribing.value=false;viaGemini.value=false;}if(audioController===currentController)audioController=undefined;}
 };
 recorder.start(1000);deadline=setTimeout(()=>stopCapture(),30000);
 }catch(cause){error.value=(cause as Error).message;stopCapture(true);}
}
function toggle(){if(listening.value){if(viaGemini.value){stopCapture(!recorder||recorder.state==='inactive');return;}try{recognition?.stop();}catch{listening.value=false;}return;}if(!constructor){if(recordingSupported)void record();return;}error.value='';recognition=new constructor();recognition.lang='es-PE';recognition.continuous=false;recognition.interimResults=false;recognition.onresult=event=>{if(disposed||props.disabled)return;let text='';for(let i=event.resultIndex;i<event.results.length;i++){const item=event.results[i];if(item?.isFinal)text+=item[0]?.transcript??'';}if(text.trim())emit('text',text.trim());};recognition.onerror=event=>{listening.value=false;error.value=event.error==='not-allowed'?'Autoriza el micrófono desde el navegador para dictar.':'El dictado no pudo completarse. Revisa micrófono, idioma y conexión.';};recognition.onend=()=>{listening.value=false;};try{recognition.start();listening.value=true;}catch{listening.value=false;error.value='No se pudo iniciar el dictado.';}}
watch(()=>props.disabled,value=>{if(value){recognition?.abort();stopCapture(true);listening.value=false;}});
onUnmounted(()=>{disposed=true;stopCapture(true);if(recognition){recognition.onresult=null;recognition.onerror=null;recognition.onend=null;recognition.abort();}});
</script>
<template><div class="speech-input"><button type="button" class="connection-action" :disabled="disabled||transcribing||(!constructor&&!recordingSupported)" :aria-pressed="listening" @click="toggle">{{ transcribing?'Transcribiendo con Gemini…':listening?'Detener dictado':constructor?'Dictar mensaje':'Dictar con Gemini' }}</button><button v-if="constructor&&recordingSupported&&!listening&&!transcribing" type="button" class="connection-action" :disabled="disabled" @click="record">Dictar con Gemini</button><button v-if="transcribing" type="button" class="connection-action" @click="stopCapture(true)">Cancelar transcripción</button><small>{{ viaGemini||!constructor&&recordingSupported?'Gemini: hasta 30 segundos de audio, consume su cuota y la aplicación no lo guarda.':constructor?'El dictado normal usa el servicio de voz del navegador, que puede procesar audio en línea. A.R.E.S. recibe texto.':'El micrófono no está disponible en este navegador.' }}</small><p v-if="error" role="status" class="result-note">{{ error }}</p></div></template>
<style scoped>.speech-input{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:12px 0}.speech-input small{font-size:10px;color:#829da8;max-width:420px}</style>
